function main(): void {
  const de = new Intl.Collator("de");
  console.log(["z", "ä", "a"].sort(de.compare));
  const en = new Intl.Collator("en");
  console.log(["b", "B", "a", "A"].sort(en.compare));
  const numeric = new Intl.Collator("en", { numeric: true });
  console.log(["a10", "a9", "a1"].toSorted(numeric.compare));
}
